      elbs: [{ id: 'alb-shop', arn: LB, name: 'shopkaro', type: 'application', scheme: 'internet-facing', subnets: ['subnet-public-a', 'subnet-public-b'], sgIds: ['sg-alb'], dns: 'shopkaro.sim.ap-south-1.elb.amazonaws.com' }],
      targetGroups: [{ arn: TG, name: 'shop-app', vpcId: 'vpc-shop', loadBalancerArn: LB, targetType: 'instance', protocol: 'HTTP', port: 8080, healthCheckPath: '/healthz', matcher: '200', targets: [1, 2, 3, 4].map(n => ({ id: 'i-app' + n, port: 8080 })) }],
      asgs: [{ name: 'shop-app', min: 4, desired: 4, max: 6, vpcZone: 'subnet-app-a', healthCheckType: 'ELB', gracePeriod: 120, instances: ['i-app1', 'i-app2', 'i-app3', 'i-app4'], targetGroupARNs: [TG], launchTemplate: { id: 'lt-shop', type: 't3.small', sgIds: ['sg-app'], healthPath: '/healthz' }, activities: [] }],
      rds: [{ id: 'shop-orders', name: 'orders', engine: 'postgres', class: 'db.t3.micro', state: 'available', multiAZ: false, encrypted: true, publicAccess: false, backupRetention: 7, deletionProtection: true, endpoint: 'shop-orders.sim.ap-south-1.rds.amazonaws.com', storage: 20 }],
      buckets: [{ name: 'shopkaro-images', region: 'ap-south-1', encryption: true, public: true, bpa: {}, policy: { Version: '2012-10-17', Statement: [{ Effect: 'Allow', Principal: '*', Action: 's3:GetObject', Resource: 'arn:aws:s3:::shopkaro-images/*' }] }, objects: [{ key: 'catalog/shoe.jpg', size: '42 KB' }] }],
