  function placement(s) {
    const g = asg(s); if (!g) return false;
    const ids = (g.vpcZone || '').split(',');
    const live = (g.instances || []).map(id => (s.account.instances || []).find(i => i.id === id));
    return ids.length === 2 && ids.includes('subnet-app-a') && ids.includes('subnet-app-b') && g.min === 4 && g.desired === 4 && g.max === 6 && live.length === 4 && live.every(i => i && i.state === 'running' && i.appHealthy !== false && ids.includes(i.subnetId) && !i.publicIp && i.sgIds.includes('sg-app')) && ['ap-south-1a', 'ap-south-1b'].every(az => live.filter(i => i.az === az).length === 2);
  }
